<?php namespace App\Repositories\MySQL; use App\Database\MySQLConnection; use App\Repositories\Interfaces\ProjectRepositoryInterface;
final class MySQLProjectRepository implements ProjectRepositoryInterface { public function __construct(private MySQLConnection $db){} public function all():array{return $this->db->pdo()->query('SELECT * FROM projects ORDER BY created_at DESC')->fetchAll();} public function featured(int $limit=3):array{$s=$this->db->pdo()->prepare('SELECT * FROM projects WHERE featured=1 ORDER BY created_at DESC LIMIT ?');$s->bindValue(1,$limit,\PDO::PARAM_INT);$s->execute();return $s->fetchAll();} public function find(string $id):?array{$s=$this->db->pdo()->prepare('SELECT * FROM projects WHERE id=?');$s->execute([$id]);return $s->fetch()?:null;} public function save(array $d,?string $id=null):string{$p=$this->db->pdo();if($id){$s=$p->prepare('UPDATE projects SET title=?,description=?,short_description=?,technologies=?,github_url=?,live_url=?,image=?,featured=?,updated_at=NOW() WHERE id=?');$s->execute([$d['title'],$d['description'],$d['short_description'],$d['technologies'],$d['github_url']?:null,$d['live_url']?:null,$d['image']?:null,(int)$d['featured'],$id]);return $id;}$s=$p->prepare('INSERT INTO projects(title,description,short_description,technologies,github_url,live_url,image,featured) VALUES(?,?,?,?,?,?,?,?)');$s->execute([$d['title'],$d['description'],$d['short_description'],$d['technologies'],$d['github_url']?:null,$d['live_url']?:null,$d['image']?:null,(int)$d['featured']]);return (string)$p->lastInsertId();} public function delete(string $id):bool{$s=$this->db->pdo()->prepare('DELETE FROM projects WHERE id=?');return $s->execute([$id]);} public function count():int{return (int)$this->db->pdo()->query('SELECT COUNT(*) FROM projects')->fetchColumn();} }
